// molly-count — runtime text fonts, GENERATED by tools/font_extract.py from
// the embedded-graphics 0.8.2 font data (fonts/raw/ascii/font_6x12.raw and
// font_9x15_bold.raw) so the C++ firmware renders pixel-identical text to
// the legacy Rust firmware. Do not edit.
//
// Layout per font: all 95 printable ASCII glyphs (32..126) back to back,
// each glyph = char_h rows of row_bytes bytes, 1bpp, MSB first — directly
// consumable by fb_blit_mask().
#pragma once

#include <stdint.h>

#define FONT6_W 6
#define FONT6_H 12
#define FONT6_ROW_BYTES 1
#define FONT6_BASELINE 9
#define FONT_GLYPHS 95 // ASCII 32..126
extern const uint8_t font6x12[FONT_GLYPHS * FONT6_H * FONT6_ROW_BYTES];

#define FONT9_W 9
#define FONT9_H 15
#define FONT9_ROW_BYTES 2
#define FONT9_BASELINE 11
extern const uint8_t font9x15_bold[FONT_GLYPHS * FONT9_H * FONT9_ROW_BYTES];
